# Now create the main entry point
cat > src/atlas/__main__.py <<'PYEOF'
"""Atlas CLI entry point."""
import os
import sys
import pkgutil

from . import texts
from . import hclfmt


def write_out(s, stream=None):
    stream = stream or sys.stdout
    stream.write(s)


def die(msg, code=1, usage=None):
    sys.stderr.write("Error: " + msg + "\n")
    if usage is not None:
        sys.stderr.write(usage)
    sys.exit(code)


# -------------------------------------------------------------------------
# A tiny cobra-like flag parser.
# -------------------------------------------------------------------------
class Flag:
    def __init__(self, name, shorthand='', takes_value=True, default=None, multi=False):
        self.name = name
        self.shorthand = shorthand
        self.takes_value = takes_value
        self.default = default
        self.multi = multi  # For "strings" flags: repeated --to=... => list
        self.value = [] if multi else default
        self.set_flag = False

    def set(self, v):
        if self.multi:
            if v is None:
                return
            # Allow comma-separated: Atlas treats `strings` as comma-separated AND repeatable.
            if isinstance(v, str):
                self.value.extend([x for x in v.split(',') if x != ''])
            else:
                self.value.append(v)
        else:
            self.value = v
        self.set_flag = True


def parse_flags(args, flags, allow_unknown=False, stop_at_non_flag=False):
    """Simple cobra-like flag parser.
    Returns (remaining_positional_args, error_or_None).
    flags is a list of Flag objects.
    """
    by_name = {f.name: f for f in flags}
    by_short = {f.shorthand: f for f in flags if f.shorthand}
    positional = []
    i = 0
    help_requested = False
    # Always include -h/--help
    while i < len(args):
        a = args[i]
        if a == '--':
            positional.extend(args[i+1:])
            return positional, None, help_requested
        if a.startswith('--'):
            eq = a.find('=')
            if eq >= 0:
                name = a[2:eq]
                val = a[eq+1:]
            else:
                name = a[2:]
                val = None
            if name == 'help':
                help_requested = True
                i += 1
                continue
            f = by_name.get(name)
            if f is None:
                if allow_unknown:
                    positional.append(a)
                    i += 1
                    continue
                return None, ('unknown flag: --' + name), help_requested
            if f.takes_value:
                if val is None:
                    if i + 1 >= len(args):
                        return None, ('flag needs an argument: --' + name), help_requested
                    val = args[i+1]
                    i += 2
                else:
                    i += 1
                f.set(val)
            else:
                if val is not None:
                    return None, ('flag does not take a value: --' + name), help_requested
                f.set(True)
                i += 1
            continue
        if a.startswith('-') and len(a) >= 2 and a != '-':
            # Short flag(s). Cobra allows `-u value` and `-uvalue` and `-abc` combined.
            sh = a[1]
            if sh == 'h':
                help_requested = True
                i += 1
                continue
            f = by_short.get(sh)
            if f is None:
                return None, ("unknown shorthand flag: '%s' in %s" % (sh, a)), help_requested
            if f.takes_value:
                rest = a[2:]
                if rest.startswith('='):
                    rest = rest[1:]
                if rest:
                    f.set(rest)
                    i += 1
                else:
                    if i + 1 >= len(args):
                        return None, ('flag needs an argument: ' + a), help_requested
                    f.set(args[i+1])
                    i += 2
            else:
                # For boolean short flags, we might have combined like -abc; but for our
                # purposes, single char suffices.
                f.set(True)
                i += 1
            continue
        # Positional
        if stop_at_non_flag:
            positional.extend(args[i:])
            return positional, None, help_requested
        positional.append(a)
        i += 1
    return positional, None, help_requested


# -------------------------------------------------------------------------
# Commands
# -------------------------------------------------------------------------
def cmd_version(args):
    flags = []
    pos, err, help_req = parse_flags(args, flags)
    if err:
        die(err)
    if help_req:
        write_out(texts.VERSION_HELP)
        return 0
    write_out(texts.VERSION_TEXT)
    return 0


def cmd_license(args):
    flags = []
    pos, err, help_req = parse_flags(args, flags)
    if err:
        die(err)
    if help_req:
        write_out(texts.LICENSE_HELP)
        return 0
    write_out(texts.LICENSE_TEXT)
    return 0


def cmd_help(args):
    """`atlas help [command...]`"""
    if not args:
        write_out(texts.ROOT_HELP)
        return 0
    # Look up nested commands
    node = ROOT
    path = []
    for a in args:
        if a.startswith('-'):
            # trailing flags ignored for help lookup
            break
        sub = node.get('subs', {}).get(a)
        if sub is None:
            sys.stdout.write("Unknown help topic [`%s`]\n" % a)
            # Show something cobra-ish: the usage of current node
            if node is ROOT:
                # Short root usage
                sys.stdout.write(_short_root_usage())
            else:
                sys.stdout.write(node.get('help', texts.ROOT_HELP))
            return 0
        node = sub
        path.append(a)
    write_out(node.get('help', texts.ROOT_HELP))
    return 0


def _short_root_usage():
    return ("Usage:\n  atlas [command]\n\nAvailable Commands:\n"
            "  completion  Generate the autocompletion script for the specified shell\n"
            "  help        Help about any command\n"
            "  license     Display license information\n"
            "  migrate     Manage versioned migration files\n"
            "  schema      Work with atlas schemas.\n"
            "  version     Prints this Atlas CLI version information.\n\n"
            'Use "atlas [command] --help" for more information about a command.\n')


def cmd_schema_fmt(args):
    flags = []
    pos, err, help_req = parse_flags(args, flags)
    if err:
        die(err)
    if help_req:
        write_out(texts.SCHEMA_FMT_HELP)
        return 0
    paths = pos if pos else ['.']
    for p in paths:
        try:
            st = os.stat(p)
        except OSError as e:
            die("stat %s: %s" % (p, os.strerror(e.errno) if e.errno else str(e)))
        if os.path.isdir(p):
            try:
                entries = sorted(os.listdir(p))
            except OSError as e:
                die("read %s: %s" % (p, os.strerror(e.errno)))
            for name in entries:
                if not name.endswith('.hcl'):
                    continue
                full = os.path.join(p, name)
                if not os.path.isfile(full):
                    continue
                _fmt_file(full)
        else:
            # It's a file - only format if .hcl extension
            if p.endswith('.hcl'):
                _fmt_file(p)
    return 0


def _fmt_file(path):
    try:
        with open(path, 'rb') as f:
            data = f.read()
    except OSError as e:
        die("read %s: %s" % (path, os.strerror(e.errno)))
    try:
        src = data.decode('utf-8')
    except UnicodeDecodeError:
        return
    new = hclfmt.format_source(src)
    if new.encode('utf-8') != data:
        try:
            with open(path, 'wb') as f:
                f.write(new.encode('utf-8'))
        except OSError as e:
            die("write %s: %s" % (path, os.strerror(e.errno)))
        print(path)


def cmd_completion(args):
    # atlas completion [shell] [--no-descriptions]
    if not args:
        write_out(texts.COMPLETION_HELP)
        return 0
    shell = args[0]
    rest = args[1:]
    if shell in ('-h', '--help'):
        write_out(texts.COMPLETION_HELP)
        return 0
    if shell not in ('bash', 'zsh', 'fish', 'powershell'):
        die('unknown command "%s" for "atlas completion"\nRun \'atlas completion --help\' for usage.' % shell)
    # parse remaining flags: --no-descriptions, -h
    flags = [Flag('no-descriptions', takes_value=False)]
    pos, err, help_req = parse_flags(rest, flags)
    if err:
        die(err)
    if help_req:
        helps = {
            'bash': texts.COMPLETION_BASH_HELP,
            'zsh': texts.COMPLETION_ZSH_HELP,
            'fish': texts.COMPLETION_FISH_HELP,
            'powershell': texts.COMPLETION_POWERSHELL_HELP,
        }
        write_out(helps[shell])
        return 0
    # Emit the completion script
    resource = 'completions/%s' % {
        'bash': 'bash.sh',
        'zsh': 'zsh.sh',
        'fish': 'fish.sh',
        'powershell': 'powershell.ps1',
    }[shell]
    data = pkgutil.get_data('atlas', resource)
    if data is None:
        die("completion script not available")
    sys.stdout.buffer.write(data)
    return 0


def _stub_db_command(name, help_text, required=None):
    """Make a stub for commands we don't implement. Just print an error."""
    def cmd(args):
        # Parse flags to validate (required ones) and show help if asked
        flag_defs = required.get('flags', []) if required else []
        pos, err, help_req = parse_flags(args, flag_defs)
        if err:
            die(err)
        if help_req:
            write_out(help_text)
            return 0
        # Check required flags
        if required:
            for req in required.get('required', []):
                f = next((f for f in flag_defs if f.name == req), None)
                if f and not f.set_flag:
                    die('required flag(s) "%s" not set' % req)
        # This is a feature we don't implement in this edition:
        die("this command is not supported in this edition")
    return cmd


