            sh = a[1]
            if sh == 'h':
                help_requested = True
                i += 1
                continue
            f = by_short.get(sh)
            if f is None:
                return None, ("unknown shorthand flag: '%s' in %s" % (sh, a)), help_requested
            if f.takes_value:
                rest = a[2:]
