def dispatch(argv):
    """Main dispatcher. argv excludes program name."""
    # Walk the command tree using argv, skipping flags along the way
    node = ROOT
    path = []
    i = 0
    help_requested = False
    while i < len(argv):
        a = argv[i]
        if a in ('-h', '--help'):
            help_requested = True
            i += 1
            continue
        if a == '--':
            break
        if a.startswith('-'):
            # Not a subcommand; remainder is for this node
            break
        subs = node.get('subs')
        if subs is None:
            break
        sub = subs.get(a)
        if sub is None:
            break
        node = sub
        path.append(a)
        i += 1
    rest = argv[i:]
    # If --help was seen at any level, show help for current node
    if help_requested:
        # Cobra: if an unknown flag is present too, it may error; but simple case:
        # just check for unknown flags only in actual run path
        write_out(node.get('help', texts.ROOT_HELP))
        return 0
    run = node.get('run')
    if run:
        return run(rest)
    # No run function: this is a group node. Behavior:
    # - If rest is empty: show help (exit 0)
    # - If rest has a non-flag word: unknown subcommand - cobra shows help (exit 0)
    #   unless top-level, which errors
    if not rest:
        write_out(node.get('help', texts.ROOT_HELP))
        return 0
    # There are remaining args. If this is ROOT, error.
    first = rest[0]
    if first.startswith('-'):
        # Unknown flag at group level
        die('unknown %s: %s' % ('flag' if first.startswith('--') else ('shorthand flag: \'%s\' in' % first[1]), first))
    if node is ROOT:
        die('unknown command "%s" for "atlas"\nRun \'atlas --help\' for usage.' % first)
    # For subcommand group with unknown subcommand: cobra just shows help
    # (with exit code 0) unless the group has SilenceErrors. Atlas seems to
    # show help and exit 0.
    write_out(node.get('help', texts.ROOT_HELP))
    return 0


def main():
    try:
        return dispatch(sys.argv[1:])
    except SystemExit:
        raise
    except KeyboardInterrupt:
        return 130


