        if a.startswith('--'):
            eq = a.find('=')
            if eq >= 0:
                name = a[2:eq]
                val = a[eq+1:]
            else:
                name = a[2:]
                val = None
            if name == 'help':
                help_requested = True
                i += 1
                continue
            f = by_name.get(name)
            if f is None:
                return None, 'unknown flag: --' + name, help_requested
            if f.takes_value:
                if val is None:
                    if i + 1 >= len(args):
                        return None, 'flag needs an argument: --' + name, help_requested
                    val = args[i+1]
                    i += 2
                else:
