def dispatch(argv):
    node = ROOT
    path = []
    i = 0
    help_requested = False
    while i < len(argv):
        a = argv[i]
        if a in ('-h', '--help'):
            help_requested = True
            i += 1
            continue
        if a == '--':
            break
        if a.startswith('-'):
            break
        subs = node.get('subs')
        if subs is None:
            break
        sub = subs.get(a)
        if sub is None:
            break
        node = sub
        path.append(a)
        i += 1
    rest = argv[i:]
    if help_requested:
        write_out(node.get('help', texts.ROOT_HELP))
        return 0
    run = node.get('run')
    if run:
        return run(rest)
    if not rest:
        write_out(node.get('help', texts.ROOT_HELP))
        return 0
    first = rest[0]
    if first.startswith('--'):
        die('unknown flag: ' + first)
    if first.startswith('-') and first != '-':
        die("unknown shorthand flag: '%s' in %s" % (first[1], first))
    if node is ROOT:
        die('unknown command "%s" for "atlas"\nRun \'atlas --help\' for usage.' % first)
    write_out(node.get('help', texts.ROOT_HELP))
    return 0


def main():
    try:
        return dispatch(sys.argv[1:])
    except KeyboardInterrupt:
        return 130


if __name__ == '__main__':
    sys.exit(main())
